parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "respuesta": {
      "type": "string",
      "description": "Mensaje para el usuario"
    },
    "nombre": {
      "type": "string",
      "description": "Nombre capturado o cadena vacía"
    },
    "dni": {
      "type": "string",
      "description": "DNI capturado tal cual o cadena vacía"
    },
    "correo": {
      "type": "string",
      "description": "Correo capturado tal cual o cadena vacía"
    },
    "completo": {
      "type": "boolean",
      "description": "true solo si ya se tienen los 3 datos y el usuario acaba de darlos/corregirlos"
    }
  },
  "required": [
    "respuesta",
    "nombre",
    "dni",
    "correo",
    "completo"
  ]
}

parameters.jsCode:
// ================== CONFIGURACIÓN EDITABLE ==================
const CFG = {
  marca: 'Soulmate',
  whatsapp: '51982770361',            // formato internacional (Perú +51) para wa.me
  whatsappVisible: '982 770 361',
  moneda: 'S/',
  heroImg: 'https://placehold.co/600x260/FF8A65/FFFFFF/png?text=Soulmate+%7C+Todo+para+tu+mejor+amigo',
  productos: [
    { nombre: 'Cama Ortopédica Cloud', desc: 'Espuma viscoelástica y funda lavable. Descanso total para tu peludito.', precio: 129.90, antes: 159.90, img: 'https://placehold.co/220x180/FFE0B2/5D4037/png?text=Cama+Cloud' },
    { nombre: 'Collar Smart con placa', desc: 'Nylon resistente, ajustable y con placa personalizable.', precio: 39.90, antes: 49.90, img: 'https://placehold.co/220x180/C8E6C9/2E7D32/png?text=Collar+Smart' },
    { nombre: 'Kit Juguetes Interactivos (5 pzs)', desc: 'Materiales no tóxicos y resistentes a mordidas.', precio: 59.90, antes: 79.90, img: 'https://placehold.co/220x180/BBDEFB/1565C0/png?text=Kit+Juguetes' }
  ]
};
// ============================================================

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const money = n => `${CFG.moneda} ${Number(n).toFixed(2)}`;

// Datos capturados por el chatbot
const d = $input.first().json.output || {};
const sessionId = $('Chat Soulmate (landing)').first().json.sessionId || 'sin-sesion';
const nombre = String(d.nombre ?? '').trim();
const dni = String(d.dni ?? '').replace(/[\s.\-]/g, '');
const email = String(d.correo ?? '').trim().toLowerCase();

// ---------- 1) Construir el promomail HTML (con imágenes) ----------
const primerNombre = esc(nombre.split(/\s+/)[0] || 'amigo');
const waLink = `https://wa.me/${CFG.whatsapp}?text=${encodeURIComponent(`Hola ${CFG.marca}, soy ${nombre} y quiero cerrar mi compra`)}`;

const filas = CFG.productos.map(p => `
    <tr>
      <td style="padding:14px 0;border-bottom:1px solid #f0e6dc;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
          <td width="140" valign="top"><img src="${p.img}" alt="${esc(p.nombre)}" width="130" style="display:block;border-radius:10px;border:0;"></td>
          <td valign="top" style="padding-left:14px;font-family:Arial,Helvetica,sans-serif;">
            <div style="font-size:17px;font-weight:bold;color:#4e342e;">${esc(p.nombre)}</div>
            <div style="font-size:13px;color:#6d6d6d;margin:4px 0 8px;">${esc(p.desc)}</div>
            <span style="font-size:22px;font-weight:bold;color:#e64a19;">${money(p.precio)}</span>
            <span style="font-size:13px;color:#9e9e9e;text-decoration:line-through;margin-left:6px;">${money(p.antes)}</span>
          </td>
        </tr></table>
      </td>
    </tr>`).join('');

const html = `<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:0;background:#fff8f1;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#fff8f1;"><tr><td align="center" style="padding:20px 10px;">
  <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:14px;overflow:hidden;">
    <tr><td><img src="${CFG.heroImg}" alt="${CFG.marca}" width="600" style="display:block;width:100%;height:auto;border:0;"></td></tr>
    <tr><td style="padding:26px 28px 6px;font-family:Arial,Helvetica,sans-serif;">
      <h1 style="margin:0 0 8px;font-size:24px;color:#4e342e;">¡Hola ${primerNombre}! 🐾</h1>
      <p style="margin:0;font-size:15px;line-height:22px;color:#555;">Gracias por registrarte en <b>${CFG.marca}</b>. Tenemos una promoción especial para ti y tu mejor amigo. Estos son nuestros precios:</p>
    </td></tr>
    <tr><td style="padding:6px 28px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${filas}</table></td></tr>
    <tr><td align="center" style="padding:24px 28px 8px;font-family:Arial,Helvetica,sans-serif;">
      <p style="margin:0 0 14px;font-size:15px;color:#555;">¿Te gustó alguno? Cierra tu compra ahora por WhatsApp:</p>
      <a href="${waLink}" style="display:inline-block;background:#25D366;color:#ffffff;text-decoration:none;font-weight:bold;font-size:16px;padding:14px 30px;border-radius:30px;">💬 Comprar por WhatsApp</a>
      <p style="margin:14px 0 0;font-size:14px;color:#4e342e;">📱 WhatsApp: <b>${CFG.whatsappVisible}</b></p>
    </td></tr>
    <tr><td style="padding:22px 28px 26px;font-family:Arial,Helvetica,sans-serif;font-size:11px;line-height:16px;color:#9e9e9e;text-align:center;">
      Recibiste este correo porque registraste tus datos en el chat de ${CFG.marca}.<br>Precios en soles, IGV incluido. Sujetos a disponibilidad.
    </td></tr>
  </table>
</td></tr></table>
</body></html>`;

// ---------- 2) Verificar datos ----------
const errores = [];
if (!/^[\p{L}][\p{L}\s.'\-]{1,59}$/u.test(nombre)) errores.push('nombre');
if (!/^\d{8}$/.test(dni)) errores.push('DNI (8 dígitos)');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errores.push('correo electrónico');

// Evita enviar dos veces la promo al mismo correo en la misma conversación
const sd = $getWorkflowStaticData('global');
sd.enviados = sd.enviados || {};
if (Object.keys(sd.enviados).length > 1000) sd.enviados = {};
const key = `${sessionId}|${email}`;
const duplicado = errores.length === 0 && !!sd.enviados[key];
const valido = errores.length === 0 && !duplicado;
if (valido) sd.enviados[key] = Date.now();

const respuestaInvalida = duplicado
  ? 'Ya te enviamos la promo a ese correo 📩 Revisa tu bandeja de entrada o spam, o escríbenos al WhatsApp 982 770 361.'
  : `No pude validar tus datos 😕 Revisa: ${errores.join(', ')}. Por favor envíamelos de nuevo (DNI de 8 dígitos y un correo válido, por ejemplo nombre@correo.com).`;

return [{ json: { valido, errores, duplicado, nombre, dni, email, asunto: `🐾 ${primerNombre}, tu promo exclusiva de ${CFG.marca} te espera`, html, respuestaInvalida } }];
